PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS settings(key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS resources(id TEXT PRIMARY KEY,type TEXT NOT NULL,path TEXT UNIQUE,title TEXT NOT NULL,sha256 TEXT,size INTEGER,mtime_ns INTEGER,revision INTEGER NOT NULL DEFAULT 1,version_id TEXT,state TEXT NOT NULL DEFAULT 'ready',metadata TEXT NOT NULL DEFAULT '{}',note TEXT NOT NULL DEFAULT '',created_at TEXT,updated_at TEXT);
CREATE TABLE IF NOT EXISTS versions(id TEXT PRIMARY KEY,resource_id TEXT NOT NULL REFERENCES resources(id),sha256 TEXT,snapshot_path TEXT,created_at TEXT);
CREATE TABLE IF NOT EXISTS groups(id TEXT PRIMARY KEY,name TEXT NOT NULL,revision INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS group_members(group_id TEXT REFERENCES groups(id),resource_id TEXT REFERENCES resources(id),PRIMARY KEY(group_id,resource_id));
CREATE TABLE IF NOT EXISTS knowledge_bases(id TEXT PRIMARY KEY,name TEXT NOT NULL,revision INTEGER NOT NULL DEFAULT 1,member_revision INTEGER NOT NULL DEFAULT 1,index_state TEXT NOT NULL DEFAULT 'empty',build_id TEXT,created_at TEXT);
CREATE TABLE IF NOT EXISTS kb_members(kb_id TEXT REFERENCES knowledge_bases(id),resource_id TEXT REFERENCES resources(id),PRIMARY KEY(kb_id,resource_id));
CREATE TABLE IF NOT EXISTS chunks(id TEXT PRIMARY KEY,resource_id TEXT REFERENCES resources(id),version_id TEXT,kind TEXT,locator TEXT,text TEXT,file_sha256 TEXT);
CREATE VIRTUAL TABLE IF NOT EXISTS chunks_fts USING fts5(chunk_id UNINDEXED,tokens,tokenize='unicode61');
CREATE TABLE IF NOT EXISTS kb_chunks(kb_id TEXT REFERENCES knowledge_bases(id),chunk_id TEXT REFERENCES chunks(id),PRIMARY KEY(kb_id,chunk_id));
CREATE TABLE IF NOT EXISTS annotations(id TEXT PRIMARY KEY,resource_id TEXT REFERENCES resources(id),version_id TEXT,pdf_nm TEXT,data TEXT,revision INTEGER DEFAULT 1,status TEXT DEFAULT 'synced');
CREATE TABLE IF NOT EXISTS relations(id TEXT PRIMARY KEY,source_id TEXT REFERENCES resources(id),target_id TEXT REFERENCES resources(id),kind TEXT,origin TEXT,status TEXT,description TEXT,evidence TEXT,revision INTEGER DEFAULT 1,created_at TEXT);
CREATE TABLE IF NOT EXISTS nodes(id TEXT PRIMARY KEY,kb_id TEXT REFERENCES knowledge_bases(id),parent_id TEXT,kind TEXT,label TEXT,origin TEXT,status TEXT,evidence TEXT);
CREATE TABLE IF NOT EXISTS jobs(id TEXT PRIMARY KEY,task TEXT,status TEXT,context TEXT,result TEXT,error TEXT,revision INTEGER DEFAULT 1,created_at TEXT,updated_at TEXT);
CREATE TABLE IF NOT EXISTS proposal_ideas(id TEXT PRIMARY KEY,title TEXT NOT NULL,description TEXT NOT NULL,resource_ids TEXT NOT NULL,knowledge_base_ids TEXT NOT NULL,revision INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS operations(id TEXT PRIMARY KEY,request_hash TEXT,kind TEXT,state TEXT,payload TEXT,result TEXT,created_at TEXT);
CREATE TABLE IF NOT EXISTS events(sequence INTEGER PRIMARY KEY AUTOINCREMENT,kind TEXT,entity_id TEXT,revision INTEGER,created_at TEXT);
PRAGMA user_version=1;
